# Helper to normalize sample names for matching
def normalize\(name\):
    """Normalize sample name for matching."""
    n = name.strip\(\)
    n = n.replace\(' ', '_'\).replace\('-', '_'\)
    n = re.sub\(r'_+', '_', n\)
    return n

# Helper to read sample names from RAWDATA
def read_rawdata_samples\(xlsx_path\):
    """Read sample names from RAWDATA xlsx."""
    samples = []
    try:
        wb = openpyxl.load_workbook\(xlsx_path, read_only=True, data_only=True\)
        # Try sheet with RAW data
        target_sheet = None
        for sn in wb.sheetnames:
            if 'RAW' in sn.upper\(\) or 'HPLC' in sn.upper\(\):
                target_sheet = sn
                break
        if not target_sheet:
            target_sheet = wb.sheetnames[0]

        ws = wb[target_sheet]
        rows = list\(ws.iter_rows\(max_row=300, values_only=True\)\)
        wb.close\(\)

        if len\(rows\) < 2:
            return samples

        # Find Sample Name column
        header = rows[0]
        sample_col = None
        for i, h in enumerate\(header\):
            if h and 'sample' in str\(h\).lower\(\) and 'name' in str\(h\).lower\(\):
                sample_col = i
                break
        if sample_col is None:
            for i, h in enumerate\(header\):
                if h and 'sample' in str\(h\).lower\(\):
                    sample_col = i
                    break
        if sample_col is None:
            return samples

        for row in rows[1:]:
            if row and len\(row\) > sample_col and row[sample_col]:
                val = str\(row[sample_col]\).strip\(\)
                if val and val.lower\(\) not in \('', 'none', 'nan'\):
                    samples.append\(val\)

    except Exception as e:
        print\(f"  ERROR: {e}"\)
    return samples

